export const BUILD_CAPACITY=3;
export const schoolFor=id=>SCHOOLS.find(s=>s.id===id);
export const schoolMatches=(s,t)=>s.cores.includes(t.core)||(s.supports||[]).includes(t.support);
export function constellationNodes(){return SCHOOLS.flatMap((s,i)=>{
 const a=-Math.PI/2+i*Math.PI/6,cx=1600+Math.cos(a)*1070,cy=1600+Math.sin(a)*1070;
 const spec=[['root','Learn '+s.name,1,2,null],['surge',s.surge,2,3,'root'],['economy',s.economy,2,3,'root'],['cadence','Living cadence',2,6,['surge','economy']],['cap',s.cap,3,12,'cadence'],['memory',s.memory,3,12,'cadence']];
 const offsets=[[0,-90],[-85,-15],[85,-15],[0,60],[-85,135],[85,135]];
 return spec.map(([step,name,cost,chapter,required],j)=>({id:`discipline:${s.id}:${step}`,school:s.id,step,name,cost,chapter,stat:'doctrine',doctrine:true,branch:8+i,requires:required===null?'origin':Array.isArray(required)?required.map(r=>`discipline:${s.id}:${r}`):`discipline:${s.id}:${required}`,x:cx+offsets[j][0],y:cy+offsets[j][1]}));
 });}
export function doctrineNodeState(s,id,node,points){const own=new Set(s.skillGrid?.[id]||[]);if(own.has(node.id))return 'learned';if(s.chapter<node.chapter&&!s.complete)return 'story';const stem=`discipline:${node.school}:`;if(node.step==='surge'&&own.has(stem+'economy')||node.step==='economy'&&own.has(stem+'surge')||node.step==='cap'&&own.has(stem+'memory')||node.step==='memory'&&own.has(stem+'cap'))return 'choice';const req=node.requires;if(req!=='origin'&&!(Array.isArray(req)?req.some(r=>own.has(r)):own.has(req)))return 'locked';return points>=node.cost?'available':'unaffordable';}
export function learnedSchool(s,id,school){const own=new Set(s.skillGrid?.[id]||[]),stem=`discipline:${school}:`;return {id:school,root:own.has(stem+'root'),surge:own.has(stem+'surge'),economy:own.has(stem+'economy'),cadence:own.has(stem+'cadence'),cap:own.has(stem+'cap'),memory:own.has(stem+'memory')};}
export function equipSchool(s,id,school,slot){const h=s.heroes[id],spec=schoolFor(school);if(s.mode==='battle'||!s.recruited.includes(id)||!Number.isInteger(slot)||slot<0||slot>1||!spec||!learnedSchool(s,id,school).root)return false;const slots=[...(h.doctrineSlots||[null,null])];slots[slot]=school;if(slots.filter(Boolean).length!==new Set(slots.filter(Boolean)).size)return false;if(slots.reduce((n,k)=>n+(schoolFor(k)?.weight||0),0)>BUILD_CAPACITY)return false;h.doctrineSlots=slots;syncDoctrines(s,id);return true;}
export function syncDoctrines(s,id){const h=s.heroes[id];if(!h.doctrineSlots&&!h.doctrineBuild)return;h.doctrineBuild=(h.doctrineSlots||[]).filter(Boolean).map(k=>learnedSchool(s,id,k)).filter(x=>x.root);}
export function clearSchool(s,id,slot){if(s.mode==='battle')return false;if(!s.heroes[id].doctrineSlots)return;s.heroes[id].doctrineSlots[slot]=null;syncDoctrines(s,id);}
export function resetConstellations(s,id){if(s.mode==='battle'||!s.recruited.includes(id))return false;s.skillGrid??={};s.skillGrid[id]=(s.skillGrid[id]||[]).filter(k=>!k.startsWith('discipline:'));s.heroes[id].doctrineSlots=[null,null];s.heroes[id].doctrineBuild=[];return true;}
export function withDoctrines(hero,tech){if(tech.doctrineApplied)return tech;let power=1,cost=0,rebate=0,mastery=0;const active=(hero.doctrineBuild||[]).filter(d=>{const s=schoolFor(d.id);return s&&d.root&&schoolMatches(s,tech);});
 for(const d of active){rebate++;if(d.surge){power+=.12;cost++;}if(d.economy){power-=.06;cost--;}if(d.cadence)rebate+=2;if(d.memory)mastery++;}
 return {...tech,power:tech.power*Math.min(1.28,power),cost:Math.max(2,Math.max(Math.ceil(tech.cost*.8),tech.cost+cost)),strainRebate:Math.min(4,rebate),masteryBonus:Math.min(2,mastery),doctrineApplied:true,doctrines:active};}
export function conditionalMultiplier(actor,target,tech){let bonus=0;for(const d of tech.doctrines||[]){if(!d.cap)continue;const rule=schoolFor(d.id)?.rule,active=rule==='burn'?target.status?.burn:rule==='slow'?target.status?.slow:rule==='wet'?target.status?.wet:rule==='calm'?actor.strain<30:rule==='wounded'?actor.hp<=actor.maxHp*.5:rule==='armor'?target.armor>0:rule==='critical'?tech.healing&&target.hp<target.maxHp*.4:rule==='guard'?actor.status?.guard:rule==='exposed'?target.status?.exposed:rule==='voices'?['link','echo','field'].includes(tech.support):false;if(active)bonus+=rule==='critical'?.18:.15;}
 return 1+Math.min(.3,bonus);}
export function doctrineDescription(node){const s=schoolFor(node.school);if(node.step==='root')return `Unlock ${s.name} as an equipped school. Capacity ${s.weight} of ${BUILD_CAPACITY}. Applies to ${s.cores.length?s.cores.join(', '):s.supports.join(', ')} recipes. While equipped, successful matching casts relieve 1 strain after payment. Learning alone grants no combat bonus.`;if(node.step==='surge')return 'Matching recipes gain 12% power and cost 1 more MP. Choose this OR the economy fork.';if(node.step==='economy')return 'Matching recipes lose 6% power and cost 1 less MP, with a global 20% discount ceiling and 2 MP minimum. Choose this OR the surge fork.';if(node.step==='cadence')return 'A successful matching cast relieves 2 strain after paying its full cost. This cannot make an unsafe cast legal.';if(node.step==='memory')return 'A successful matching cast earns +1 core AP. Choose this OR the conditional combat capstone.';return `Matching recipes gain ${s.rule==='critical'?18:15}% power ${s.condition}. Combined conditional bonuses cannot exceed 30%. Choose this OR the mastery capstone.`;}
